<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {ArrowRight,Compass,X} from 'lucide-vue-next'
import {useApp} from '../stores/app'
import type {Depth} from '../types'
const app=useApp(),selected=ref<string[]>([]),depth=ref<Depth>('beginner'),busy=ref(false),error=ref(''),dialog=ref<HTMLElement|null>(null)
function toggle(id:string){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
async function finish(skip=false){busy.value=true;error.value='';try{await app.update({familiar_disciplines:skip?[]:selected.value,depth:depth.value,onboarding_complete:true,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone});app.notify('你的探索档案已建立，随时可以修改设置。')}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
function trap(e:KeyboardEvent){if(e.key==='Escape'&&!busy.value){void finish(true);return}if(e.key!=='Tab')return;const nodes=dialog.value?.querySelectorAll<HTMLElement>('button,select,input,a[href]');if(!nodes?.length)return;const first=nodes[0]!,last=nodes[nodes.length-1]!;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
onMounted(()=>{document.body.style.overflow='hidden';document.addEventListener('keydown',trap);dialog.value?.focus()});onUnmounted(()=>{document.body.style.overflow='';document.removeEventListener('keydown',trap)})
</script>
<template><div class="modal-backdrop"><section ref="dialog" tabindex="-1" class="onboarding modal" role="dialog" aria-modal="true" aria-labelledby="onboarding-title"><button class="icon-button modal-close" aria-label="跳过设置" @click="finish(true)" :disabled="busy"><X :size="20"/></button><div class="welcome-icon"><Compass :size="28"/></div><p class="eyebrow">A LITTLE CONTEXT, A BIGGER WORLD</p><h1 id="onboarding-title">你的已知，是探索的起点。</h1><p class="lead">告诉我们你熟悉的领域，让新的知识与你已有的认知建立联系。也可以直接开始，世界足够大。</p><div class="field-label">哪些领域，你已经有些了解？ <span>可多选 · 可跳过</span></div><div class="discipline-options"><button v-for="d in app.disciplines" :key="d.id" :class="['option-pill',{selected:selected.includes(d.id)}]" :aria-pressed="selected.includes(d.id)" @click="toggle(d.id)"><i :style="{background:d.color}"/>{{d.name}}</button></div><label class="field-label" for="start-depth">你希望从什么深度开始？</label><select id="start-depth" v-model="depth"><option value="beginner">入门 · 用简单语言理解基本原理</option><option value="intermediate">进阶 · 连接原理、背景和应用</option><option value="deep">深入 · 更多机制与开放问题</option></select><p v-if="error" class="inline-error" role="alert">{{error}}</p><div class="modal-actions"><button class="text-button" @click="finish(true)" :disabled="busy">跳过，直接探索</button><button class="button primary" @click="finish()" :disabled="busy">{{busy?'正在保存…':'开始我的探索'}}<ArrowRight :size="18"/></button></div><p class="privacy-note">无需注册。档案通过浏览器匿名身份识别，清除 Cookie 可能无法继续访问。</p></section></div></template>
